INSERT INTO div_trip_inspection_templates(inspection_type,version_no,title,enabled,entry_enabled) VALUES ('TI_CONVENTIONAL','VVH-2025-08-SOURCE','Conventional Loco Trip Inspection — approved source VVH-2025-08',1,1) ON DUPLICATE KEY UPDATE title=VALUES(title),enabled=1,entry_enabled=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'सामान्य ळम्छम्त्।स्','i','Check driver booking in log book; if any booking exists, inform shed via TLC.','लॉग बुक में ड्रायवर बुकिंग चेक करें और यदि कोई बुकिंग है तो टीएलसी द्वारा शेड को सूचित करें।','चेक किया ब्ीमबामक',1,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'सामान्य ळम्छम्त्।स्','ii','Check Fault Messages Logged in FDCS and Take appropriate action. Check screen for proper working, any breakage or cracks.','एफडीसीएस में दर्ज फॉल्ट संदेशों की जांच करें और उचित कार्रवाई करें। स्क्रीन के सही कार्य, किसी भी टूट-फूट या दरार की जाँच करें।','Normal',2,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Seat','i','Check looseness, squaring, and cracks of all parts; repair any defective parts.','सभी पूर्जों की लूजनेंस , स्‍कोयरिंग तथा क्रैक की जॉच करें । यदि कोई खराब मिले तो उसे रिपेयर करें।','Intact',3,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','i','Check cleanliness & working of lamps and gauges on driver’s desk.','चालक की डेस्क पर लगे दीपकों और गेजों की सफाई और कार्यशीलता की जांच करें।','Normal',4,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','ii','Ensure BP, FP, MR, BC, AFI, U-meter, gauges readings are correct.','बीपी, एफपी, एमआर, बीसी, एएफआई गेजेस की रिडींग सही होना सुनिश्चित करें।','Normal',5,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','iii','Ensure emergency push button switch operates correctly.','एमरजेंसी  पुश बटन स्विंच की सही कार्य कर रहा है सुनिश्चित करें ।','Working',6,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','iv','Check working of BPVG, PVEF, PVSA, PVCD etc.','BPVG, PVEF, PVSA, PVCD आदि के कार्य करने की स्थिति जांचें।','Normal',7,1 WHERE @trip_template_new=1;
