INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','14','Check working of SPM & any abnormal report about SPM in defect log book, if not working same to attend.','गतिमापक यंत्र का कार्यरत होना सुनिश्चित करें, यदि खराब है तो ठीक करें','Working Normal.',14,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','15','Check availability of memory card','मेमोरी कार्ड की उपलब्धता जांचें।','Available/Replaced',15,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','16','Check the PG connection for proper tightness','पी जी के कनेेक्शन टाईटनैस चेक करें ।','Intact',16,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','17','Check working of cab heaters & cab AC','कैब हीटर व कैब एसी के कार्यरत होना सुनिश्चित करें','Working normal.',17,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','18','Check Look out Glass for condition & cleanliness.','लुक आउट ग्लास की स्थिति और साफ-सफाई की जाँच करें।','Intact/Clean',18,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','19','Check the condition of Door glass, Window glass & Sun wiser/Sun screen','डोर ग्लास, विंडो ग्लास और सन वाइजर/सन स्क्रीन की स्थिति की जांच करें।','Intact',19,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','20','Check door lock & door hinges','डोर लॉक और डोर हिंग्स की जांच करें।','Working',20,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','21','Check for any inflammable foreign material on loco.','ज्वलनशील बाहरी पदार्थ की जांच करें','Check & Removed',21,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','xv.','Check for any crackness & intactness of Foot steps & Doors','फुट स्टेप्स और दरवाजों में किसी भी दरार तथा उनकी मजबूती की जाँच करें।','Intact',22,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','xvi','Check the position of all program switches. i. e. 0/1/3. Attend if 0 or 3','सभी प्रोग्राम स्विच का कार्यरत होना सुनिश्चित करें जैसे 0/1/3 स्थिति । यदि 0/3 पर हो तो दुरुस्त करें ।','Normal position 1',23,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','xvii','Check the working of ZCPA programme switch for position.','जेडसीपीए स्विच का कार्यरत होना सुनिश्चित करें ।','ZCPA Operation & Baby Compressor working normal.',24,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items:','xviii','Check the proper fitment/tightness of BPP, BPR, BPT, BPSW, BPQD, BPQWC & ZLC switches in both cabs.','दोनों कैब में बीपीपी बीपीआर बीपीटी बीपीएसडब्ल्यू बीपीक्यूडी बीपीक्यूडब्ल्यूसी बीपीक्यूसी और ज़ेडएलसी स्विचों की सही फिटमेंट/कसाव की जांच करें।','Intact & working normal',25,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','i','Check all lighting, bulbs of cabs and corridors, cab fan if deficient or not working, attend accordingly.','कैब और गलियारों की सभी लाइटें बल्ब तथा कैब फैन की जाँच करें। यदि कोई कमी हो या काम न कर रहा हो, तो आवश्यकतानुसार ठीक करें।','Intact & is working condition.',26,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','ii','Check working of flasher, tail and marker light and clean glasses.','टेल लाईट, फ्लैशर लाईट व मार्कर लाईट को चैक करंे तथा उनके ग्लास को साफ करें ।','In working condition.',27,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','iii','Ensure working of both flasher lights on Auto/Manual position.','फ्लैशर लाईट का आटो/मैन्युल स्थिति में कार्यरत होना सुनिश्चित करें ।','In working condition.',28,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','iv','Check the working of head light with DC-DC converter positions','डीसी-डीसी कन्वर्टर की विभिन्न स्थितियों के साथ हेड लाइट के कार्य की जाँच करें। अ) मोड-1 ंद्धच्वेपजपवद.प् ब) मोड-2 इद्धच्वेपजपवद.प्प्','Both position working normal',29,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','v','Check the working of LV meter, Ammeter, CHBA Ammeter and Volt meter of loco.','एल वी मीटर, अमीटर, सीएचबीए, अमीटर तथा वोल्टमीटर की जाॅच करें ।','Working normal',30,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','vi','Check working of all wipers, replace blade if required.','सभी वाइपर के संचालन की जांच करें, आवश्यकता होने पर ब्लेड बदलें।','Working normal',31,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','vii','Check working of Horns (LV & HV)','सभी हार्न को कार्यरत होना सुनिश्चित करें । (एलवी/एचवी)','Working normal',32,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','viii','Check the operation of BL board keys, ZPT, reverser keys & switches for slackness.','बीएल, जेडपीटी त्था रिवर्सर की चाॅवी व स्विच की जाॅच करें । सुनिश्चित करें कि कोई स्विच स्लैक तो नहीं है ।','Free operation',33,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटिंग स्प्ळभ्ज्प्छळ','ix','Check Hand brake & its operation.','हैंड ब्रेक और उसके संचालन की जांच करें।','Working normal',34,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','i','inspect the entire upper structure of the pantograph assembly and check that the assembly horn, wear strip and support assembly have no cracks.','पैन्‍टोग्राफ असेंबली के पूरे ऊपरी ढॉचे की विजुअल जॉच करें तथा जॉच करें कि असेम्‍बली हॉर्न विअर स्‍ट्रीप तथा सपोर्ट असेम्‍बली में कोई क्रेक नहीं। टपेनंससल','No Crack',35,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','ii','Check for bent or twisted pan, leakage in operating cylinder and correct condition of damper and pan spring.','बेंड या झुका पॅन, ऑपरेटिंग सिलींडर में लिकेज तथा डॅम्‍पर एवं पॅन स्‍प्रींग की सही स्थिति चेक करें ।','Normal',36,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','iii','Check if pan head locking pin springs are properly installed. Verify pin movement in the frame; if not proper, check if the head is misaligned.','पैन हेड लॉकिंग पीन स्‍प्रीगस सही तरह से लगी हुई है या नहीं चेक करें। फ्रेम में पीन की मूवमेंट सही है या नहीं चेक करें यदि ना हो तो देखे हेड टेडा तो नहीं है ।','Normal',37,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','iv','Check tightness of connecting shunt screw; if loose, fit a new screw. Inspect the shunt; it should be intact.','कनेक्टिंग शंट स्क्रू की टाइटनेस जांचें; यदि ढीला हो, तो नया स्क्रू लगाएं। शंट की जांच करें; वह सही स्थिति में (अक्षत) होना चाहिए।','Normal',38,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','v','Check proper operation of pantograph including raising (in three steps) and lowering (in three steps). Adjust if needed.','पैंटोग्राफ की सही कार्यप्रणाली की जांच करें, जिसमें तीन चरणों में उठाना और तीन चरणों में नीचे करना शामिल है। आवश्यकता होने पर समायोजन करें।','Raising 6-9 sec, Lowering within 10 sec',39,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','vi','check for any cracks.','फुट माऊंटिग  इंसुलेटर को साफ करें और चेक करे कि कोई क्रेक तो नहीं है । ब्समंद विवज उवनदजपदह पदेनसंजवत ंदक','Clean/No crack',40,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','vii','Check thickness of carbon strip of both pantographs. Ref:- RDSO/2007/EL/SPEC/0054, Rev. 3','दोनों पेंटोग्राफ की कार्बन पट्टी की मोटाई की जाँच करें।','13.5mm min (IR03) 26mm min (Schunk WBL-85 HS/HR) 24mm min',41,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','viii','Check upper thrust of both the pantograph. IR03- On 7.0Kgf, Panto pan should not leave OHE while on 7.5Kgf, panto pan should leave OHE by a paper gap between OHE & Panto pan. HRPT- After putting 7.0Kgf, pull the panto pan towards lower side, it must be stop wherever pulling force removed. Similarly, during application of upper force, Panto pan should stop wherever upper force removed.','दोनों पेंटोग्राफ के ऊपरी थ्रस्ट की जाँच करें। दोनों पैंटोग्राफ की अपर थ्रस्ट की जांच करें। IR03 - 7.0 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन को ओएचई (OHE) से अलग नहीं होना चाहिए, जबकि 7.5 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन और ओएचई के बीच कागज़ की मोटाई जितना अंतर आ जाना चाहिए। HRPT - 7.0 किलोग्राम-फोर्स (Kgf) लगाने के बाद पैंटो पैन को नीचे की ओर खींचें, खींचने की ताकत हटते ही पैंटो पैन को वहीं रुक जाना चाहिए। इसी प्रकार, जब ऊपर की ओर बल लगाया जाए, तो बल हटते ही पैंटो पैन को वहीं रुक जाना चाहिए।','7.0 किलोग्राम 7ण्0 ज्ञहि',42,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph & Roof Equipments','ix','Ensure PRV setting of HRPT Pantograph is within limit. Ref:- RDSO letter no. No. EL/2.2.1/High Reach/Faiveley)','सुनिश्चित करें कि एचआरपीटी पैंटोग्राफ की पीआरवी सेटिंग सीमा के भीतर है।','ैीनदा ;ॅठस्.85द्ध भ्त्.3ण्6.4ण्1ठंत ैीनदा ;ॅठस्.85द्ध भ्ै.3ण्5.3ण्6 ठंत थ्ंपअमसमल स्ग् 3600. 4ण्8.5ण्1ठंत थ्ंपअमसमल स्ग् 3800. 3ण्8.4ण्1ठंत',43,1 WHERE @trip_template_new=1;
