INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','i','Check the battery voltage, it should be minimum 90volt. If voltage found less, Electrolyte to be check.','बैटरी वोल्टेज की जाँच करें यह न्यूनतम 90 वोल्ट होना चाहिए। यदि वोल्टेज कम पाया जाए, तो इलेक्ट्रोलाइट की जाँच करें।','Record Battery voltage',67,1 WHERE @trip_template_new=1;
