INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','iv','Record the battery voltage with switch HBA in “ON” condition (voltage should be 98 to 100V). If found battery voltage less, specific gravity to be check.','HBA स्विच ‘ON’ स्थिति में रखते हुए बैटरी वोल्टेज रिकॉर्ड करें (वोल्टेज 98 से 100 V होना चाहिए)। यदि वोल्टेज कम पाया जाए, तो विशिष्ट गुरुत्व (specific gravity) की जांच करें।',';98.100द्ध अवसज',70,1 WHERE @trip_template_new=1;
