INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','i','Check condition of brake block and change if required.  Adjust the piston stroke Check the gap between brake block & wheel in brake release condition 10mm & for WAG7 it should be 6mm).','ब्रे्रेक ब्लाक को चेक करें, यदि आवश्यकता होे तब बदली करे । पिस्टन सट्रोक का समायोजन करें) लोको ब्रेक रिलीज करे पहिये से ब्रेक ब्लाॅक के बिच का अंतराल जाॅंचे (10 मिमी अधिकतम) ॅ।ळध्7 (6 मिमी अधिकतम) ॅ।ळ5ए ॅ।ड4 दृ 95 जव 105 उउ ॅ।ळ7 दृ 107 जव 117उउ ॅ।च्1-4.68 जव 78 उउ ॅब्।ड3 दृ 105 जव 117 उउ ;','Condemned brake block changed and brake piston stroke adjusted.',95,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','ii','Ensure that there is no rubbing mark of brake blocks on wheel flange.','सुनिश्चित करें कि ब्रेक ब्लॉक की कोई रबिंग मार्क व्हील फ्लैन्ज़ पर न हो।','Normal',96,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','iii','Check brake cylinder for proper operation, ensure no air leakage.','ब्रेक सिलींडर के कार्य को जाॅंचे व सुनिश्चित करे कि हवा का रिसाब नही है ।','No leakage, normal operation',97,1 WHERE @trip_template_new=1;
