INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','xii','Check working of all sanders & condition of sand gear equipments.','सँडर व्यवस्था सभी सैंडर्स के कार्य एवं सैंड गियर उपकरणों की स्थिति की जांच करें। ैंदक ळमंत मुनपचउमदजे','Intact & Working',106,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','xiii','Intactness of Cover bolts. Provision of split pin-----','एक्सल बाॅक्स ।गसम इवग कव्हर बोल्ट लगे है स्पलिट पिन लगी है एक्सल बाॅक्स टिल्ंिटग (डब्ल्यु अे पी 1 एवं 4 लोको','Intact Available',107,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','xiv','Secondary Spring','प्र्राइमरी स्ंिप्रग च्तपउंतल ैचतपदह सेकंडरी स्ंिप्रग','Breakage/Shifting. Breakage/Shifting.',108,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','xv','Bolster of WAP-4 & WAP-1 locos. Friction piston pin','डब्लुएपी 4, डब्लुएपी 1 लोको को बोल्टसर जाॅचे क्रॅक्र ब्तंबाण् फ्रिक्शन पिस्टन पिन लाइनर स्पदमत बतंबाण्','Intact No crack',109,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'यांत्रिक डम्ब्भ्।छप्ब्।स्','xvi','Check intactness of connection strap bolts at all wheels Check Trunion position at all wheels Ensure clearance between connections to guide strip in WAP-1 & WAP-4 locos. Ensure no rubbing of connection strap with wheel of WAP-1 & WAP-4 locos at all wheels Check vertical & lateral play of hangers Check intactness of brake hanger top pin, split pin & safety sling. Check Trunion locking with split pin & proper oiling in WAP-1 & WAP-4 locos. Ensure safety sling for connection strap in WAP-1 & WAP-4 locos.','डब्लुएपी 1, डब्लुएपी 4 की ब्रेक रिगिंग क)   सभी व्हिल के कनेक्शन स्ट्रेप बोल्ट का लगा होना सुनिश्चित करे ख)  सभी व्हिल के ट्रा यूनियन की स्थिती की जाॅच करे घ)  डब्लुएपी 1, डब्लुएपी 4 लोको में गाइड स्ट्रिप तथा कनेक्शन के बीच में क्लिअरन्स सुनिश्चित करे । बद्ध ड)  डब्लुएपी 1, डब्लुएपी 4 लोको में सभी व्हिल के कनेक्शन स्ट्रिप का चक्को से ना धिसना सुनिश्चित करे । कद्ध च)  हैंगर में व्हर्टिकल व लेटरल प्ले चेक करे छ)  ब्रेक हॅंगर की टाॅप पिन, स्पलिट पिन, सेफ्टी स्ंिलग का लगे होने की जाॅच करें । ज)  डबलु एपी 1, डबलु एपी 4 लोको में ट्रायूनियन लाॅकिंग स्पलिट पिन व उचित आॅयलिंग की जाॅच करे । हद्ध ह)   डब्लु एपी 1, डब्लु एपी 4 लोको में कनेक्शन स्ट्रिप की सेफ्टी स्ंिलग का होना सुनिश्चित करें । ीद्ध ठतंाम त्पहहपदह व िॅ।च्.1 - ॅ।च्.4ण्','Intact Intact Intact Intact Intact Intact Intact Intact',110,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','111','FP hose pipes.','दोनो कैब में लगे  बीपी तथा एफपी ऐगल कॉक ओपन तथा क्‍लोज पोजीशन में कार्य –जॉच करें जिसमे डमीके साथ लगे कॅलीब्रेटेड बीपी एफपी गेज लगे है । बीपी तथा एफपी फ्लेक्‍झीबल होस तथा एंगल कॉक में एयर लिकेज की जॉच करें बीपी / एफपी होज़ पाइप में कोई डैमेज न हो, यह सुनिश्चित करें। ब्ीमबा जीम वचमतंजपवद व िठच् ंदक थ्च् ंदहसम बवबो पद इवजी बंइे पद वचमद ंदक बसवेमक चवेपजपवदे ूपजी बंसपइतंजमक ठच् ंदक थ्च् हंनहमे बवददमबजमक ूपजी जीम कनउउलण् ।सेव बीमबा वित ंपत समंांहम पद ठच् ंदक थ्च् सिमगपइसम ीवेमे ंदक ंदहसम बवबोण् म्देनतम जीमतम पे दव कंउंहम पद जीम ठच्','Operation Normal',111,1 WHERE @trip_template_new=1;
