INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'।चचरू 8.12 ेमब त्मसरू 12.15 ेमब','x','Apply loco brake & test loco on power, loco should not move 80% of continuous rating','लोेको में ब्रेक लगाकर ब्रेक पावर चेक करें । लोकों 80ः व िबवदजपदनवने तंजपदह पर नही हिलना चाहिए','ॅ।ळ7डए ॅ।च्1-4ए छवज जव उवअम.800। डवअम.1000। ॅ।ळ.5-7 छवज जव उवअम.600। डवअम.800। ॅब्।ड.3 720 । ॅब्।ळ.1 720 ।',146,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'।चचरू 8.12 ेमब त्मसरू 12.15 ेमब','xi.','Top up lubrication oil in all Compressors.','सभी कोमपे्रसर में तेल भरे','Oil filled up',147,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'।चचरू 8.12 ेमब त्मसरू 12.15 ेमब','xii.','Check the working of unloader valve check for any leakage.','अनलोडर वाल्व के कार्य व हवा के रिसाव की जाॅच करे','Normal',148,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_templates(inspection_type,version_no,title,enabled,entry_enabled) VALUES ('TI_3PHASE','VVH-2025-08-SOURCE','Trip Inspection Proforma for 3-Phase Locos — approved source VVH-2025-08',1,1) ON DUPLICATE KEY UPDATE title=VALUES(title),enabled=1,entry_enabled=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'जनरल ळम्छम्त्।स्','i','Check driver booking in log book; if any booking exists, inform shed via TLC.','लॉग बुक में ड्रायवर बुकिंग चेक करें और यदि कोई बुकिंग है तो टीएलसी द्वारा शेड को सूचित करें।','चेक किया ब्ीमबामक',1,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'जनरल ळम्छम्त्।स्','ii','check.','एक राउंड ट्रिप की DDS लॉगिंग की जांच करें। क्क्ै सवहहपदहे वित वदम तवनदक जतपच जव इम','चेक किया ब्ीमबामक',2,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'जनरल ळम्छम्त्।स्','iii','Check that there is no damage to the loco body structure.','लोको बॉडी स्‍ट्रक्‍चर में कोई डेंमेज नहीं है यह चेक करें।','No damage',3,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Rail Guard & Cattle Guard','i','Check and adjust the height of the rail guard.','रेल गार्ड की ऊॅचाई की जॉच करें और समायोजित करें','Height within 105 to 120 mm.',4,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Rail Guard & Cattle Guard','ii','Check the tightness of the nut and bolts of the cattle guard.','केटल गार्ड की नट- बोल्‍ट की टाईटनेस जॉच करें।','Intact',5,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Rail Guard & Cattle Guard','iii','Check Cattle guard for any crack or gap.','कैटल गार्ड में किसी भी दरार या अंतर की जांच करें।','Intact',6,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Seat','i','Check looseness, squaring, and cracks of all parts; repair any defective parts.','सभी पूर्जों की लूजनेंस , स्‍कोयरिंग तथा क्रैक की जॉच करें । यदि कोई खराब मिले तो उसे रिपेयर करें।','Intact',7,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','i','Ensure transparent rubber caps on push buttons in driver’s cab.','ड्रायव्‍हर कैब में लगी पुश बंटन पर लगे ट्रान्‍सपरंट रबर कैप का होना सुनिश्चित करें।','लगा है थ्पजजमक',8,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','ii','Check cleanliness & working of switches, lamps and gauges on driver’s desk.','चालक की डेस्क पर लगे स्विच, दीपक और मीटर की सफाई और कार्यशीलता की जांच करें','Normal',9,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','iii','Ensure BP, FP, MR, BC, AFI, U-meter, gauges readings are correct.','बीपी, एफपी, एमआर, बीसी, एएफआई गेजेस की रिडींग सही होना सुनिश्चित करें।','Normal',10,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','iv','Ensure emergency push button switch operates correctly.','एमरजेंसी  पुश बटन स्विंच की सही कार्य कर रहा है सुनिश्चित करें ।','Working',11,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Driver’S Desk','v','Check working of BPVG, PVEF, PVSA, PVCD etc.','BPVG, PVEF, PVSA, PVCD आदि के कार्य करने की स्थिति जांचें।','Normal',12,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Cab Heater, Cab Cooler Fan And Cab Ac','i','Check operation and effectiveness of cab heater, cab blower, cab fan, cab AC.','कैब हिटर/ब्लोअर, कैब कूलर फैन और कैब एसी की कार्य एवं कुशलता चेक करें।','Working',13,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'स्‍पीडोमीटर ैच्म्म्क्व्डम्ज्म्त्','i','Note down Date, time, KM Earned and status of memory. Check display light & intactness of all connection.','तिथि, समय, अर्जित किलोमीटर एवं मेमोरी की स्थिति नोट करें। डिस्प्ले लाइट एवं सभी कनेक्शनों की सुदृढ़ता की जांच करें।','चेक किया ब्ीमबामक',14,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'स्‍पीडोमीटर ैच्म्म्क्व्डम्ज्म्त्','ii','Inspect pulse generator protection cover, cable and coupler for damage.','पल्‍स जनरेटर का प्रोटेक्‍शन कव्‍हर, केबल तथा कपलर के डॅमेज की जॉंच करें।','No Damage',15,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items','i','Wooden wedges (4 Nos. each)','लकडी के गुटके','Available',16,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items','ii','Fire extinguisher (4 Nos. each)','अग्निशमन (कुल सं. - 4)','Available',17,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items','iii','LV Board (01 No.)','एल.वी. बोर्ड (कुल सं. - 1)','Available',18,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items','iv','Screw coupling safety clamp (01 No.)','स्क्रू कपलिंग सेफ़्टी क्लैम्प (कुल सं. - 1)','Available',19,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Check The Availability Of Following Safety Items','v','Spare BP & FP Hose pipe (01 No. each)','अतिरिक्त BP एवं FP होज़ पाइप (प्रत्येक-1)','Available',20,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Doors And Footsteps','i','Check the operation of external door locks, Machine room door & its locks and inspect for any damage & attend accordingly.','दरवाजे के  बाहरी ताले, मशीन रूम का दरवाज़ा और उसके ताले के कार्य की जॉच करें तथा कोई डॅमेज है या नही देखे एवं अनुसार कार्यवाही करें ।','Working',21,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Doors And Footsteps','ii','Check condition of all footsteps','सभी पायदानों की स्थिति की जांच करें।','Intact',22,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Look Out Glass And Side Window','i','Clean the lookout glass with detergent/water. Clean dust and debris from sliding window glass.','लुकआउट ग्लास को डिटर्जेंट/पानी से साफ करें। स्लाइडिंग विंडो ग्लास से धूल एवं मलबा साफ करें।','साफ किया ब्समंदमक',23,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Look Out Glass And Side Window','ii','Check operation of window screen and side window & their Locking features; replace if cracked or scratched. Also check condition of external standing plate for Look out glass.','विंडो स्क्रीन एवं साइड विंडो तथा उनके लॉकिंग फीचर्स की कार्य स्थिति जांचें; यदि दरार या खरोंच हो तो बदलें। साथ ही लुकआउट ग्लास के लिए बाहरी स्टैंडिंग प्लेट की स्थिति की भी जांच करें।','Intact',24,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'परीक्षण ज्म्ैज्प्छळ','i','Perform HT testing of the locomotive and ensure all equipment is functioning properly & check for any unusual noise from Auxiliary Machines.','लोकोमोटिव का HT परीक्षण करें और सुनिश्चित करें कि सभी उपकरण सही तरीके से कार्य कर रहे हैं तथा सहायक मशीनों से किसी भी प्रकार की असामान्य आवाज़ की जांच करें।','Normal',25,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Horn And Horn Switch','i','Check LT & HT horn valves of both cabs and its operation.','दोनों कैब के LT एवं HT हॉर्न वाल्व तथा उनके संचालन की जांच करें।','Normal',26,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Washer/Wiper','i','Check all wiper parts for wear, looseness, cracks and its operation with manual handle and repair if faulty.','सभी वाइपर के पुर्जों की घिसावट, ढीलापन, दरार एवं उनके मैनुअल हैंडल से संचालन की जांच करें और खराब होने पर मरम्मत करें।','Working',27,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Washer/Wiper','ii','Check water tank level for wipers and refill as needed. Ensure washers are working properly.','वायपर्स के पानी की टंकी के पानी की मात्रा चेक करे तथा जरूरत होने पर भर दें वाशरर्स को सही तरह से कार्यरत होने के लिए चेक करें।','Water filled',28,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटस् स्प्ळभ्ज्ै','i','Clean the glass of headlight lamps and marker lights.','हेड लाईट लॅम्‍प एवं मार्कर लाईट के कॉच साफ करें।','साफ किया ब्समंदमक',29,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'लाईटस् स्प्ळभ्ज्ै','ii','Check operation of flasher light, marker light, headlight, cab light, desk light, and machine room light.','फ्लेशर लाईट मार्करलाईट हेड लाईट कैब लाईट डीस्‍क लाईट मशीनरूम लाईट का ऑपरेशन चेक करें।','Working Condition',30,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Simulation Mode','31','Check the working of the following: No Air leakage from VCB and SR contactors. Working of TE/BE up to Full traction and braking operation. Dropping of TE/BE through RS & A-9. Working of VCD through BPVG, foot switch, BPVR and application of penalty brakes from both cabs.','निम्नलिखित की कार्य स्थिति की जांच करें: a) VCB एवं SR कॉन्टैक्टर्स से किसी भी प्रकार का एयर लीकेज न हो।b) पूर्ण ट्रैक्शन एवं ब्रेकिंग ऑपरेशन तक TE/BE का सही तरीके से कार्य करना।c) RS एवं A-9 के माध्यम से TE/BE का ड्रॉप होना।d) BPVG, फुट स्विच, BPVR के माध्यम से VCD का कार्य करना तथा दोनों कैब से पेनाल्टी ब्रेक का लगना।','चेक किया ब्ीमबामक',31,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','i','inspect the entire upper structure of the pantograph assembly and check that the assembly horn, wear strip and support assembly have no cracks.','पैन्‍टोग्राफ असेंबली के पूरे ऊपरी ढॉचे की विजुअल जॉच करें तथा जॉच करें कि असेम्‍बली हॉर्न विअर स्‍ट्रीप तथा सपोर्ट असेम्‍बली में कोई क्रेक नहीं। टपेनंससल','No Crack',32,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','ii','Check for bent or twisted pan, leakage in operating cylinder, and correct condition of damper and pan spring.','बेंड या झुका पॅन, ऑपरेटिंग सिलींडर में लिकेज तथा डॅम्‍पर एवं पॅन स्‍प्रींग की सही स्थिति चेक करें ।','Normal',33,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','iii','Check if pan head locking pin springs are properly installed. Verify pin movement in the frame; if not proper, check if the head is misaligned.','पैन हेड लॉकिंग पीन स्‍प्रीगस सही तरह से लगी हुई है या नहीं चेक करें। फ्रेम में पीन की मूवमेंट सही है या नहीं चेक करें यदि ना हो तो देखे हेड टेडा तो नहीं है ।','Normal',34,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','iv','Check tightness of connecting shunt screw; if loose, fit a new screw. Inspect the shunt; it should be intact.','कनेक्टिंग शंट स्क्रू की टाइटनेस जांचें; यदि ढीला हो, तो नया स्क्रू लगाएं। शंट की जांच करें; वह सही स्थिति में (अक्षत) होना चाहिए।','Normal',35,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','v','Check proper operation of pantograph including raising (in three steps) and lowering (in three steps). Adjust if needed.','पैंटोग्राफ की सही कार्यप्रणाली की जांच करें, जिसमें तीन चरणों में उठाना और तीन चरणों में नीचे करना शामिल है। आवश्यकता होने पर समायोजन करें।','Raising 6-9 sec, Lowering within 10 sec',36,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','vi','check for any cracks.','फुट माऊंटिग  इंसुलेटर को साफ करें और चेक करे कि कोई क्रेक तो नहीं है । ब्समंद विवज उवनदजपदह पदेनसंजवत ंदक','Clean/No crack',37,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','vii','Check thickness of carbon strip of both pantographs.','दोनों पेंटोग्राफ की कार्बन पट्टी की मोटाई की जाँच करें।','13.5mm min (IR03) 26mm min (Schunk WBL-85 HS/HR) 24mm min',38,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','viii','Check upper thrust of both the pantograph. IR03- On 7.0Kgf, Panto pan should not leave OHE while on 7.5Kgf, panto pan should leave OHE by a paper gap between OHE & Panto pan. HRPT- After putting 7.0Kgf, pull the panto pan towards lower side, it must be stop wherever pulling force removed. Similarly, during application of upper force, Panto pan should stop wherever upper force removed.','दोनों पेंटोग्राफ के ऊपरी थ्रस्ट की जाँच करें। दोनों पैंटोग्राफ की अपर थ्रस्ट की जांच करें।IR03 - 7.0 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन को ओएचई (OHE) से अलग नहीं होना चाहिए, जबकि 7.5 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन और ओएचई के बीच कागज़ की मोटाई जितना अंतर आ जाना चाहिए।HRPT - 7.0 किलोग्राम-फोर्स (Kgf) लगाने के बाद पैंटो पैन को नीचे की ओर खींचें, खींचने की ताकत हटते ही पैंटो पैन को वहीं रुक जाना चाहिए। इसी प्रकार, जब ऊपर की ओर बल लगाया जाए, तो बल हटते ही पैंटो पैन को वहीं रुक जाना चाहिए।','7.0 किलोग्राम 7ण्0 ज्ञहि',39,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','ix','Ensure PRV setting of HRPT Pantograph is within limit. Ref:- RDSO letter no. No. EL/2.2.1/High Reach/Faiveley)','सुनिश्चित करें कि एचआरपीटी पैंटोग्राफ की पीआरवी सेटिंग सीमा के भीतर है।','ैीनदा ;ॅठस्.85द्ध भ्त्.3ण्6.4ण्1ठंत ैीनदा ;ॅठस्.85द्ध भ्ै.3ण्5.3ण्6 ठंत थ्ंपअमसमल स्ग् 3600. 4ण्8.5ण्0ठंत थ्ंपअमसमल स्ग् 3800. 3ण्8.4ण्2ठंत',40,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pantograph','x','If any crack observed in Panto pan, Panto horn, same panto to be replaced.','यदि पैंटो पैन या पैंटो हॉर्न में कोई दरार दिखाई दे, तो उसी पैंटो को बदल दिया जाए।','Normal',41,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Roof Equipment','i','Inspect pantograph insulator, high voltage bushing insulator, VCB surge arrester, primary voltage transformer insulator, roof bar insulator etc., for cracks, flash marks, or damage. Also checked intactness of mounting bolts of all insulators.','पेंटोग्राफ इंसुलेटर, हाई वोल्टेज बुशिंग इंसुलेटर, VCB सर्ज अरेस्टर, प्राइमरी वोल्टेज ट्रांसफॉर्मर इंसुलेटर, रूफ बार इंसुलेटर आदि में दरार, फ्लैश मार्क या क्षति की जांच करें। साथ ही सभी इंसुलेटर के माउंटिंग बोल्ट की सुदृढ़ता की भी जांच करें।','Intact',42,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Roof Equipment','ii','if present.','पेंटोग्राफ इंसुलेटर, हाई वोल्टेज बुशिंग इंसुलेटर, VCB सर्ज अरेस्टर, प्राइमरी वोल्टेज ट्रांसफॉर्मर इंसुलेटर, रूफ बार इंसुलेटर आदि को साफ करें तथा यदि तार, कपड़े के टुकड़े, पॉलिथीन आदि जैसे कोई बाहरी पदार्थ मौजूद हों तो उन्हें हटा दें। ब्समंद चंदजवहतंची पदेनसंजवतए ीपही अवसजंहम इनेीपदह पदेनसंजवतए टब्ठ ेनतहम ंततमेजमतए चतपउंतल अवसजंहम जतंदेवितउमत पदेनसंजवतए तवव िइंत पदेनसंजवत मजब - तमउवअम ंदल वितमपहद उंजमतपंसे ेनबी ंे ूपतमेए बसवजी चपमबमेए चवसलजीमदम मजबण्','साफ किया ब्समंदमक',43,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Roof Equipment','iii','Check for any cracks on roof and roof joints','छत की व छत के जोडो पर दरार की जाॅच करें ।','No cracks',44,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Roof Equipment','iv','Check for overheating and damage of harmonic filter resistor mounted on roof. Clean to remove any external debris & check intactness of mounting bolts.','छत के ऊपर लग हारमोनिक फिल्‍टर रजिस्‍टर की ओवर हीटिंग तथा डॅमेज की जॉंच करें । उसे साफ करें ताकि बाहरी कोई कचरा नही रहे और माउंटिंग बोल्ट की स्थिति की जाँच करें ।','Intact',45,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','i','Check the oil level indicator on the both conservators of Transformer and ensure there is no leakage. Ensure Oil level of both conservator of TFP should be between min and max level.','ट्रांसफॉर्मर के दोनों कंजरवेटर पर तेल स्तर संकेतक की जांच करें और सुनिश्चित करें कि कोई रिसाव न हो। TFP के दोनों कंजरवेटर का तेल स्तर न्यूनतम और अधिकतम स्तर के बीच होना चाहिए।','No Leakage/ level Between min and max',46,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','ii','Check main transformer and its cover for cracks, breakage, or leaks.','मेन ट्रान्‍सफार्मर एवं उसके कव्‍हर में क्रेक , टूटफूट या लिकेज की जॉच करें।','No Damage',47,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','iii','Check pipe couplings and flexible hose flanges fitted on transformer and conservator.','ट्रांन्‍सफॉर्मर तथा कंजरवेटर में लगे पाईप कपलिंग तथा फ्लेक्झिबल होस फ्लेज की जांच करें।','Intact',48,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','iv','Check the earthing cable.','अर्थिंग केबल की जांच करें।','Intact',49,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','v','if it has turned Pink.','सिलीका जेल यदि गुलाबी हो तो उसे बदल दें। त्मचसंबम ेपसपबं हमस','ब्‍लू ठसनम',50,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Transformer','vi','Check both TFP oil pumps for oil leakage and abnormal noise; take corrective action as needed.','दोनों TFP ऑयल पंप में तेल रिसाव एवं असामान्य शोर की जांच करें; आवश्यकता अनुसार सुधारात्मक कार्यवाही करें।','No Leakage',51,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','i','Check the coolant level indicator on the both convertors and ensure there is no leakage. Ensure coolant level of both convertors should be between min and max level.','दोनों कन्वर्टर पर कूलेंट स्तर संकेतक की जांच करें और सुनिश्चित करें कि कोई रिसाव न हो। दोनों कन्वर्टर का कूलेंट स्तर न्यूनतम और अधिकतम स्तर के बीच होना चाहिए।','No Leakage/ level Between min and max',52,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','ii','Check SR coolant spy (level indicator) glass condition for any coolant leakage.','SR कूलेंट स्पाई (लेवल इंडिकेटर) ग्लास की स्थिति में किसी भी कूलेंट रिसाव की जांच करें।','No Leakage',53,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','iii','Check for loose or missing body cover screws and repair as needed.','कवर की लूज या निकल हुए स्‍कू की जॉच करें यदि जरूरत हो तो सुधारे।','No Leakage',54,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','iv','Check both flange joints of SR cooling pump for any oil leakage.','SR कूलिंग पंप के दोनों फ्लैंज जोड़ों की जांच करें कि कहीं ऑयल लीकेज तो नहीं है।','No Leakage',55,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','v','check for external damage & oil leakage from OCB radiator.','OCB रेडिएटर में किसी भी बाहरी क्षति एवं तेल रिसाव की दृश्य जांच करें। टपेनंससल','No Leakage',56,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Converter','vi','Check both SR coolant pumps for coolant leakage and abnormal noise; take corrective action as needed.','दोनों SR कूलेंट पंप में कूलेंट रिसाव एवं असामान्य शोर की जांच करें; आवश्यकता अनुसार सुधारात्मक कार्यवाही करें।','No Leakage',57,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','i','Inspect all traction motors for breakage, dents, or other defects; Ensure air vents are not blocked and TM Bellow is not Torn.','सभी टीएम की टूटफूट डेन्‍ट या अन्‍य खराबी की जॉच करें, यह सुनिश्चित करें कि हवा की निकासी ब्‍लॉक नहीं होनी चाहिए और TM बेलो फटा हुआ न हो।','No Damage',58,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','ii','Check the temperature indicator strip on TM for any abnormal temperature increase.','टीएम के तापमान में असामान्य वृद्धि के लिए तापमान संवेदन पट्टी की जाँच" करे।','Checked normal',59,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','iii','Check traction motor power cable for any rubbing and overheating.','ट्रैक्शन मोटर पावर केबल में किसी भी प्रकार की रगड़ या अधिक गर्मी की जाँच करें।','No Damage',60,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','iv','Check condition of spheribloc TM1 to TM6 and ensure support arms are intact. Crack in spheriblocs should not be more than 180 Degrees','टी एम 1 से 6 तक के स्‍फेरीब्‍लॉक्‍स की स्थिति चेक करें तथा इनका सपोर्ट आर्म का ठीक होना सुनिश्चित करें| स्फेरिब्लॉक में क्रैक 180 डिग्री से अधिक नहीं होना चाहिए।','No Crack',61,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','v','Check TM mounting bogie nose for any crack & TM mounting nose foundation for welding off.','TM माउंटिंग बोगी नोज़ में किसी भी दरार एवं TM माउंटिंग नोज़ फाउंडेशन में वेल्डिंग के टूटने की जांच करें।','Normal',62,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','vi','Check condition of torque arm with nut bolt.','नट-बोल्ट सहित टॉर्क आर्म की स्थिति की जांच करें।','Normal',63,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Traction Motor','vii','Check intactness of nut bolts of spheri-bloc, TM mounting bogie nose for TM suspension, TM holding plate with bolt, TM holding plate J-Bracket with bolt.','स्फेरी-ब्लॉक के नट-बोल्ट, TM माउंटिंग बोगी नोज़ के TM सस्पेंशन हेतु, TM होल्डिंग प्लेट के बोल्ट, तथा TM होल्डिंग प्लेट J-ब्रैकेट के बोल्ट की सुदृढ़ता की जांच करें।','Normal',64,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hb Panel, Sb Panel, Fb Cubicle & Auxiliary Machines Mounting','i','Check that all support plates, doors & mounting bolts fitted in SB, HB panels and FB cubicle are properly installed.','एसबी, एफबी तथा एचबी में लगे सभी सपोर्ट प्‍लेट, दरवाज़े एवं माउंटिंग बोल्ट सही तरह से लगे है , चेक करें ।','Normal',65,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hb Panel, Sb Panel, Fb Cubicle & Auxiliary Machines Mounting','ii','Check all MCBs installed in SB and HB panels and ensure that the MCBs are set.','SB और HB पैनल में लगे सभी MCB की जांच करें और MCB सेट होने सुनिश्चित करें।','Normal',66,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hotel Load','i','Check that both Hotel Load Converters (HLC) installed in the loco are in working condition and ensure that the input, output and healthy lamps on both HLCs are illuminated.','लोको में लगे दोनों होटल लोड कन्वर्टर (HLC) की कार्यशील स्थिति की जांच करें तथा दोनों HLC पर लगे इनपुट, आउटपुट और हेल्दी लैम्प का प्रकाशित होना सुनिश्चित करें।','Working',67,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hotel Load','ii','Ensure the illumination of LSHO lamp and HLC-1, 2 ON command lamps installed on the driver desk.','ड्राइवर डेस्क पर लगे LSHO लैम्प और HLC -1, 2 ON कमांड लैम्प का प्रकाशित होना सुनिश्चित करें।','Working',68,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hotel Load','iii','Check all fault messages logged in the HLC/Log book and take appropriate action.','HLC/लॉग बुक में दर्ज सभी दोषसंदेशों (fault messages) की जाँच करें और तदनुसार उचित कार्रवाई करें।','चेक किया ब्ीमबामक',69,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Hotel Load','iv','Inspect the IVC and UIC couplers, its locking arrangement & its pins installed in the loco for any damage or breakage.','लोको में लगे IVC और UIC कपलर, उनके लॉकिंग प्रबंध एवं पिन की किसी भी प्रकार की क्षति या टूट-फूट के लिए जांच करें।','No damage',70,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Ocb (Oil Cooling Blower)','i','Record the air delivery measurements of OCB in under frame at middle of radiator side wall.','रेडिएटर साइड वॉल के मध्य में अंडरफ्रेम में स्थित OCB की एयर डिलीवरी माप को रिकॉर्ड करें।','Normal (8.0m/s)',71,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Vcd (Visual Control Device)','i','Check whether VCD is isolated through isolating switch 237.1 or through DDS loggings.','जांच करें कि VCD को आइसोलेशन स्विच 237.1 के माध्यम से या DDS लॉगिंग्स के द्वारा आइसोलेट किया गया है या नहीं।','Normal',72,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Vcd (Visual Control Device)','ii','Ensure vigilance control device works properly.','विजीलेंस कंट्रोल डिवाईस का सही कार्य करना सुनिश्चित करें।','Working',73,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','i','inspect the battery box for any external damage, its hanging support & condition of battery cables.','बैटरी बॉक्स की किसी भी बाहरी क्षति, उसके हैंगिंग सपोर्ट एवं बैटरी केबलों की स्थिति की दृश्य जांच करें। टपेनंससल','Intact',74,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','ii','apply petroleum jelly if found dry.','बैटरी सेल के टर्मिनल को साफ करें, यदि सूखा पाया जाए तो पेट्रोलियम जेली लगाएँ। ब्समंद जीम जमतउपदंस व िइंजजमतल बमससए','साफ किया ब्समंदमक',75,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','iii','Check locking of Battery box cover.','बैटरी बॉक्स कवर की लॉकिंग की जांच करें।','Normal',76,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','iv','Record the battery voltage with switch 112.1 in “ON” at SB-2 panel in machine room (voltage should be 95 to 105V).','मशीन रूम में SB-2 पैनल पर स्विच 112.1 को “ON” स्थिति में रखकर बैटरी वोल्टेज रिकॉर्ड करें (वोल्टेज 95 से 105V के बीच होना चाहिए)।',';95.105द्धटवसजे',77,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','v','Record the on load voltage with MCPA working.','MCPA के कार्यरत होने पर ऑन लोड वोल्टेज रिकॉर्ड करें।','(अंतर 2 वोल्ट से अधिक नहीं होना चाहिए) (Difference should not be more than 2 Volts)',78,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','vi','Record the CHBA voltage.','CHBA वोल्टेज रिकॉर्ड करें।','110 अवसजे',79,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Battery','vii','Check the function of MCPA with BL switch in “D” Mode.','BL स्विच को “D” मोड में रखकर MCPA के फंक्शन की जांच करें।','चेक किया ब्ीमबामक',80,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','i','Check both cabs transition screw coupling and apply general purpose grease to it.','लोकोमोटिव के दोनों ओर सीबीसी के ट्रांजिशन स्क्रू कपलिंग पर सामान्य प्रयोजन ग्रीस लगाएं।','Checked/ Grease Applied',81,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','ii','Check the availability of CBC bottom support plate bolts.','सी.बी.सी. बॉटम सपोर्ट प्‍लेट बोल्‍ट की उपलब्‍धता की जॉच करें।','Intact',82,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','iii','Check whether the CBC operating handle is functional.','सी.बी.सी.ऑपरेटिंग हैंडल कार्यरत है या नहीं जॉच करें।','Working',83,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','iv','inspect the CBC striker casting assembly.','सी.बी.सी.स्‍ट्राइकर कॉस्‍टींग एसेंम्‍ब्‍ली व्हिजुयली चेंक करें। टपेनंससल','Working',84,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','v','Measure CBC height of both ends.','दोनों छोर की सीबीसी ऊंचाई मापें','1030मिमी से 1105मिमी 1030उउ जव 1105उउ',85,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Draft Gear And Coupler','vi','Check operation of both ends CBC & Ensure locking pin to be inserted & locking properly.','दोनों सिरों के CBC के संचालन की जांच करें और सुनिश्चित करें कि लॉकिंग पिन डाली गई हो और ठीक से लॉक हो रही हो। ।','Working',86,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Loco Side & Buffer','i','Apply general purpose grease on both side faces and head plunger of loco side buffer.','लोको साइड बफर के दोनो साइड फेस तथा हेडप्‍लांजर में जनरल परपस ग्रीस लगाए।','Grease Applied',87,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Loco Side & Buffer','ii','Check the foundation bolts of all buffers for tightness or any other defects noticed in buffer assembly.','सभी बफ़र्स के फाउंडेशन बोल्टों की कसावट या बफर असेंबली में देखे गए किसी अन्य दोष की जांच करें।','Tight & Intact',88,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Loco Side & Buffer','iii','Check visually the tightness of filters of MRB, TMB, HLC.','MRB, TMB, HLC के फिल्टरों की कसावट को दृष्टि परीक्षण द्वारा जांचें।','Intact',89,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Sanding Equipment','i','Check working of all sanders & condition of sand gear equipments & filled with dry sand.','सभी सैंडर्स के संचालन की जांच करें और सैंड गियर उपकरणों की स्थिति का परीक्षण करें—साथ ही यह सुनिश्चित करें कि वे सूखे रेत से भरे हों।','Filled & Working',90,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'सस्‍पेंशन ैन्ैच्म्छैप्व्छ','i','Check for cracks or damage in primary and secondary helical springs in between Bogie-Body & in between Axle box-Bogie.','बोगी-बॉडी के बीच एवं एक्सल बॉक्स-बोगी के बीच में प्राथमिक और द्वितीयक हेलिकल स्प्रिंग्स में दरार या क्षति की जांच करें।','No Crack/ No Damage',91,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'सस्‍पेंशन ैन्ैच्म्छैप्व्छ','ii','Check oil leakage and condition of nut bolt of all dampers.','सभी डॅम्‍परो का ऑइल लिंकेज तथा नट बोल्‍ट की स्थिति की जांच करें।','No Leakage/ Normal',92,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'सस्‍पेंशन ैन्ैच्म्छैप्व्छ','iii','Inspect spheribloc of axle guide links on wheels 1 to 12 for cracks. Crack in spheriblocs should not be more than 270 Degrees','एक्‍सल गार्डड लिंक की स्‍फेरीब्‍लाकों की स्थिति  जॉच करें व्‍हील न.1 से 12 तक सभी  स्‍फेरीब्‍लॉक चैक करें कि क्रेक नहीं हैं | स्फेरिब्लॉक में क्रैक 270 डिग्री से अधिक नहीं होना चाहिए।','No Crack',93,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','i','Check for looseness, wear and damaged parts in brake rigging.','ब्रेक रीगींग का लूजनेस, घीसाव तथा डॅमेज पार्ट का निरीक्षण करें।','No Loose/ Damage',94,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','ii','Inspect bogie frame and damper base for cracks or damage.','बोगी फ्रेम एवं या डॅम्‍पर बेस का क्रॅक अथवा  डेंमेज के लिए निरीक्षण करें।','No Crack',95,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','iii','Check pneumatic pipeline system for air leakage.','न्‍युमेंटिक पाइप लाईन सिस्‍टम के लिकेज की जांच करें।','No Leakage',96,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','iv','Check earthing shunt fitted in between bogie and body.','बोगी और बॉडी के बीच फिट किया गया अर्थिंग शंट जांचें।','100 प्रतिशत 100ः',97,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','v','Inspect brake gear for wear, looseness, damage, hanging and pulling parts with cotter pins.','ब्रेक गियर की घिसावट, ढीलापन, क्षति, लटकते एवं खिंचने वाले पुर्जों की कॉटर पिन सहित जांच करें।','Intact',98,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','vi','Check correct position of bogie-I and bogie-II, isolation cock.','बोगी। तथा बोगी-।। आयसोलेशन कॉक सही स्थिति में होने की जॉच करें।','ओपन वचमद',99,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','vii','Check all lock nuts on underframe (WAP-7).','अंडर फ्रेम में लगे सभी लॉक नटस् की जॉच करें (WAP-7)।','Intact',100,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','viii','Check safety slings of brake adjusting device & all brake hangers & check availability of locking plate on pins of all brake hangers.','ब्रेक एडजस्टिंग डिवाइस एवं सभी ब्रेक हैंगर्स के सेफ्टी स्लिंग्स की जांच करें तथा सभी ब्रेक हैंगर्स के पिन पर लॉकिंग प्लेट की उपलब्धता की जांच करें।','Available',101,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','ix','Check hole condition of pull rod according to wheel diameter, play of all brake hangers, all brake hanger for cracks and wear & intactness of all brake hanger tie bar with its safety sling. Also, ensure brake adjusting devices are correct & check if threaded bolts of adjusting equipment are bent & inspect mounting plate of adjusting equipment; if found abnormal, replace them.','व्हील डायामीटर के अनुसार पुल रॉड के छेद की स्थिति, सभी ब्रेक हैंगर का प्ले, सभी ब्रेक हैंगर में दरार एवं घिसावट तथा सभी ब्रेक हैंगर टाई बार की सुदृढ़ता एवं उनके सेफ्टी स्लिंग की जांच करें। साथ ही, यह सुनिश्चित करें कि ब्रेक एडजस्टिंग डिवाइस सही हैं और एडजस्टिंग उपकरण के थ्रेडेड बोल्ट मुड़े हुए तो नहीं हैं, इसकी जांच करें तथा एडजस्टिंग उपकरण की माउंटिंग प्लेट का निरीक्षण करें; यदि कोई असामान्यता पाई जाए तो उन्हें बदल दें।','Normal',102,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','x','Check condition of TBU & PBU (in WAP-5 & WAG-9).','TBU और PBU की स्थिति की जांच करें (WAP-5 एवं WAG-9 में)।','Intact',103,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Frame And Brake Gear','xi','Check the brake blocks for wear; replace if any block is below minimum limit (as per the marking).','ब्रेक ब्‍लॉक घिसा हुआ है या नहीं जॉंच करें। यदि कोई ब्रेक ब्‍लॉक न्‍यूनतम सीमा के नीचे पाए तो ब्रेक ब्‍लॉक बदले (निशान के अनुसार )।','Normal',104,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Wheel Set And Axle Box','i','If there is any crack that requires wheel replacement.','यदि कोई क्रैक हो जिसके लिए व्‍हील बदलना पडे।','No Crack',105,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Wheel Set And Axle Box','ii','If there is skidding observed or reported than checked for condition of wheel sets.','यदि स्किडिंग देखी या रिपोर्ट की गई हो, तो व्हील सेट्स की स्थिति की जांच करें।','No Skid',106,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Wheel Set And Axle Box','iii','Measure the root wear, flange wear and tread wear of the loco wheel. Wheel wear measurement should be within given limit.','लोको के व्हील की रूट वियर, फ्लैंज वियर और ट्रेड वियर का माप लें। पहिये के घिसाव का माप इस सीमा के भीतर होना चाहिए।','Flange wear – below 3.0 mm Root wear – Tread wear – below 6.5 mm',107,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Wheel Set And Axle Box','iv','Ensure axle cover bolts are properly installed and earthing return shunts are fitted from axle box to body and bogie to body.','एक्‍सल कव्‍हर बोल्‍ट सही तरीके से लगा होना सुनिश्चित करें तथा एक्‍सल बॉक्‍स से बॉडी और बोगी से बॉडी में अर्थ रिटर्न शंट लगा होना सुनिश्चित करें।','Intact',108,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Wheel Set And Axle Box','v','Check Axle box holder for proper fitment & ensure correct orientation of pin on middle axle box.','एक्सल बॉक्स होल्डर की उचित फिटमेंट जांचें और मध्य एक्सल बॉक्स पर पिन की सही दिशा सुनिश्चित करें।','Intact',109,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','i','Check the push-pull rod pivot head for any damage in both ends of both Bogies.','दोनों बोगियों के दोनों सिरों पर पुश-पुल रॉड पिवट हेड में किसी भी प्रकार की क्षति की जांच करें।','Damage',110,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','ii','Inspect the traction link assembly for any defects.','ट्रॅक्‍शन लिंक असेंब्‍ली का किसी भी खराबी के लिए निरीक्षण करें','Damage',111,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','iii','Check the nuts and bolts securing the traction rod at both ends. If loose, replace them and tighten to the specified torque (26Kgcm). Ensure the locking plate is intact in both ends of both Bogies.','दोनों बोगियों के दोनों सिरों पर ट्रॅक्‍शन रॉड की सुरक्षा के लिए उसके दोनो छोर पर लगेू नट बोल्‍टस को चेंक करें। ढीले पाए जाने पर उन्‍हें नए लगाए तथा उन्‍हें निर्देशित टॉर्क (26किग्रा से.मी.) से टाइट करें। लॉकिंग प्‍लेट का ठीक होना सुनिश्चित करें।','Intact',112,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','iv','Inspect safety slings, pins and R-clips for wear and damage.','सेफ्टी स्‍लींग , पीन तथा आर क्‍लीप के घीसाव एवं डॅमेंज का निरीक्षण करें।','In good condition',113,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','v','Inspect the aclathan ring for cracks and shifting in both ends of both Bogies.','दोनों बोगियों के दोनों सिरों पर अॅक्‍लाथन रींग की क्रेंक एवं शिफ्टिंग का निरीक्षण करें ।','Intact',114,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'ट्रैक्‍शन बार ज्त्।ब्ज्प्व्छ ठ।त्','vi','Check that all bolts of the inner (6 bolts) and outer (6 bolts) retaining ring of the aclathan ring housing & locking plates are in proper condition. If loose, replace them and tighten to the specified torque (08Kgcm) in both ends of both Bogies.','दोनों बोगियों के दोनों सिरों पर एक्लाथन रिंग हाउसिंग की इनर (6 बोल्ट) और आउटर (6 बोल्ट) रिटेनिंग रिंग तथा लॉकिंग प्लेट्स के सभी बोल्ट सही स्थिति में हैं या नहीं, इसकी जांच करें। यदि कोई ढीले हों, तो उन्हें बदलें और निर्दिष्ट टॉर्क (08 किग्रा से.मी.) तक कसें।','Intact',115,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Gear Case','i','ensure no oil leakage or external damage. Check that the protective cover of sight glass is properly fitted.','गियर केस तथा इसके स्पाई ग्लास बाहर से साफ करें और निरीक्षण करें कि कोई तेल का लीकेज नहीं है तथा बाहर से कोई डॅमेज नहीं है । स्‍पाई ग्‍लास के प्रो‍टेक्टिव कव्‍हर का ठीक से लगा होना सुनिश्चित करें। ब्समंद जीम हमंत बंेम ंदक पजे ेचल हसंेे मगजमतदंससलए','No Leakage Fitted properly',116,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Gear Case','ii','Check oil level from gear case spy glass; add oil if needed. Verify drain plug fitting, tightness and sealing.','गियर केस के स्पाई ग्लास से ऑइल लेवल की जॉच करें तथा जरूरत हो तो ऑईल डाले ड्रेन प्‍लग का सही तरह से लगा होना और उसकी टाईटनेस तथा सिलिंग चेक करें।','चेक किया ब्ीमबामक',117,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Gear Case','iii','Inspect all nuts and bolts on the gear case and replace the broken bolts, if any.','गियर केस में लगे हुए सभी नट बोल्‍ट की जॉंच करें , यदि कोई बोल्‍ट टूटा मिले तो उसे बदल दे।','No Damage',118,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Gear Case','iv','Ensure intactness of Breather & its cap.','ब्रीदर और उसके कैप की अखंडता सुनिश्चित करें।','Intact',119,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','i','Check for vibration of the compressor, abnormal noise, proper operation, any external body damage & any damage in support bracket.','कंप्रेसर में वाइब्रेशन, असामान्य शोर, सही संचालन, बाहरी शरीर में कोई क्षति एवं सपोर्ट ब्रैकेट में कोई क्षति की जाँच करें।','Normal',120,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','ii','check pipes and support clamps for condition and leakage. Ensure protection guards on compressor are intact & safety slings are fitted on both compressors. Also, visually check compressor fan blades.','पाइप्स और सपोर्ट क्लैम्प्स की स्थिति एवं लीकेज की दृश्य जांच करें। सुनिश्चित करें कि कंप्रेसर पर लगे प्रोटेक्शन गार्ड सुरक्षित हैं और दोनों कंप्रेसरों पर सेफ्टी स्लिंग्स लगे हुए हैं। साथ ही, कंप्रेसर के फैन ब्लेड्स की भी दृश्य जांच करें। टपेनंससल','No Damage/ No Leakage',121,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','iii','Check oil level and condition; top up as necessary.','आयल की लेवल एवं आयल की कंडिशन चेक करें जरूरत पडे तो आयल भरे ।','Normal',122,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','iv','Check the time taken by compressor to build from 0Kg/cm2 to cut-out with Air dryer & both compressors working If found abnormal, check the time taken by compressor to build 0Kg/cm2 to cut-out with Air dryer & one-by-one single compressor working','एयर ड्रायर के साथ और दोनों कंप्रेसर कार्यरत स्थिति में, 0Kg/cm² से कट-आउट प्रेशर तक दबाव बनाने में कंप्रेसर द्वारा लिया गया समय जांचें।यदि समय असामान्य पाया जाए, तो एयर ड्रायर के साथ एक-एक करके केवल एक कंप्रेसर के कार्यरत होने पर 0Kg/cm² से कट-आउट प्रेशर तक दबाव बनाने में लिया गया समय जांचें।','4 min (max) Only CP-1 working – 7 min (max) Only CP-2 working – 7 min (max)',123,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','v','Check the working of unloader valve and control air pressure pipe of NRV for any leakage.','अनलोडर वाल्व के कार्य एवं NRV की कंट्रोल एयर प्रेशर पाइप में किसी भी प्रकार की लीकेज की जांच करें।','Normal',124,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Main Compressor','vi','check BP drop & Auto-flasher working','RS वाल्व को संचालित करें और BP प्रेशर ड्रॉप तथा ऑटो-फ्लैशर की कार्यप्रणाली की जांच करें। त्ै अंसअम जव इम वचमतंजम -','Working properly',125,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Auxiliary Compressor','i','Check oil level and condition; top up as needed.','आयल की लेवल एवं आयल की कंडिशन चेक करें जरूरत पडे तो आयल भरे।','Normal',126,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Auxiliary Compressor','ii','Check sufficient pressure build up by auxiliary compressor for raising of pantograph.','पेंटोग्राफ उठाने हेतु सहायक कंप्रेसर द्वारा पर्याप्त दबाव बनने की जांच करें।','Normal',127,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Auxiliary Compressor','iii','Check tightness of all foundation bolts and nuts.','सभी फाऊंडेशन बोल्‍ट एवं नट की टाईटनेस जॉच करें।','Normal',128,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Auxiliary Compressor','iv','Drain the Moisture from Auxiliary Compressor.','ऑक्‍झीलीयरी कंप्रेसर  से  मॉइश्चर को ड्रेन करें।','ड्रेन किया /Drained',129,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Air Dryer','i','Inspect air dryer for damage and check for air leakage in Air Dryer-CP pipeline.','डॅमेज हेतु एयर ड्रायर का निरीक्षण करें । एयर ड्रायर – सीपी पाईपलाईन से एयर लिकेज चेक करें।','No Leakage',130,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Air Dryer','ii','Check hanging support welding condition.','हॅगींग सपोर्ट की वेल्डिंग की सही स्थिति चेक करें।','Normal',131,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Air Dryer','iii','Check proper working of air dryer & position of its isolating cock ‘A’, ‘B’, ‘C’.','एयर ड्रायर के सही कार्य एवं उसके आइसोलेटिंग कॉक ‘A’, ‘B’, ‘C’ की स्थिति की जांच करें।','Normal',132,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','i','Check operation of A-9 & SA-9 brakes.','A-9 एवं SA-9 ब्रेक के संचालन की जांच करें।','Working properly',133,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','ii','Check free movement of brake controller.','ब्रेक कंट्रोलर की फ्री  मूवमेंट  चेक करें।','Working properly',134,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','iii','Apply and release brakes repeatedly from both cabs and ensure BP, BC pressure build-up and drop correctly.','दोनों केब से ब्रेक को बार-बार लगाकर और छोड़कर जांचें, और सुनिश्चित करें कि BP एवं BC प्रेशर सही तरीके से बढ़ और घट रहे हैं।','Working properly',135,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','iv','Loco Type','लोको प्रकार','Brake via A-9 Full Service/ Emergency',136,1 WHERE @trip_template_new=1;
