INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','139','ॅ।च्.5',NULL,'5ण्15 ज्ञहध्बउ2',139,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','v','Loco Type','लोको प्रकार','Brake via SA-9 Full Applied',140,1 WHERE @trip_template_new=1;
