INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','viii','Apply A9 to full service, the BC pressure should not exceed 2.5kg/cm², Press PVEF, the loco brakes should be released. Apply A9 to emergency, BC pressure should be 2.5 kg/cm², press PVEF, the loco brakes remain in applied condition.','लोको ब्रेक्स की संयोजन क्रिया की जांच करें: a) A9 को फुल सर्विस पोजीशन में लगाएं, BC प्रेशर 2.5 kg/cm² से अधिक नहीं होना चाहिए। PVEF दबाएं, लोको ब्रेक्स रिलीज हो जाने चाहिए। b) A9 को इमरजेंसी पोजीशन में लगाएं, BC प्रेशर 2.5 kg/cm² होना चाहिए। PVEF दबाएं, लोको ब्रेक्स लगे हुए ही रहने चाहिए। ंद्ध इद्ध ब्वदरनदबजपवद ूवतापदह व िसवबव इतंामेरू','Intact',145,1 WHERE @trip_template_new=1;
