INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','xiii','Apply loco brake & test loco on power, loco should not move up to 150 KN','लोेको में ब्रेक लगाकर ब्रेक पावर चेक करें । लोकों 150 KN पर नही हिलना चाहिए','स्थानांतरित नहीं हुआ छवज उवअमक',151,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'A-9, Sa-9 और Rs वाल्व ।.9ए ै।.9 - त्ै ट।स्टम्','xiv','Check the gap between brake block & wheel in brake release condition should be 10 mm). Ref:- RDSO’s SMI No.197-2001 Rev-1, Amendment dated 26/30-07-2001.','पिस्टन स्ट्रोक समायोजित करें WAP-7/WAG-9 – 107 से 117 मिमी (ब्रेक रिलीज स्थिति में ब्रेक ब्लॉक और व्हील के बीच का गैप 10 मिमी होना चाहिए)। ।करनेज जीम चपेजवद ेजतवाम ॅ।च्7ध्ॅ।ळ9 दृ 107 जव 117उउ ;','Condemned brake block changed and brake piston stroke adjusted.',152,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pneumatic Panel','i','inspect the pneumatic panel for any air leakage.','वायु रिसाव के लिए न्यूमैटिक पैनल का दृश्यात्मक निरीक्षण करें। टपेनंससल','No Leakage',153,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pneumatic Panel','ii','Check position of cut-out and isolating cock.','कटआऊट तथा आयसोलेटिंग कॉक की सही पोजीशन की जॉच करें ।','Normal',154,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Pneumatic Panel','iii','Check position all Electro-Pneumatic connectors.','सभी इलेक्ट्रो-प्नीयूमैटिक कनेक्टर्स की स्थिति जांचें।','Intact',155,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Bogie Brake Isolating Cock','i','Check correct position of Bogie-1 &2 Isolating cocks & its protection cover.','बोगी-1 एवं बोगी-2 के आइसोलेटिंग कॉक और उनके प्रोटेक्शन कवर की सही स्थिति की जांच करें।','Intact',156,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Air Reservoir','i','Ensure no hit marks on Air reservoir and check the proper operation of the drain cock. Also, ensure air reservoir foundation bolts are tight and intact.','सुनिश्चित करें कि एयर रेसर्वायर पर कोई हिट मार्क न हो और ड्रेन कॉक के सही संचालन की जांच करें। साथ ही, एयर रेसर्वायर के फाउंडेशन बोल्ट सख्त और सुदृढ़ होने चाहिए।','No Damage',157,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','i','FP hose pipes.','दोनो कैब में लगे  बीपी तथा एफपी ऐगल कॉक ओपन तथा क्‍लोज पोजीशन में कार्य –जॉच करें जिसमे डमीके साथ लगे कॅलीब्रेटेड बीपी एफपी गेज लगे है । बीपी तथा एफपी फ्लेक्‍झीबल होस तथा एंगल कॉक में एयर लिकेज की जॉच करें बीपी / एफपी होज़ पाइप में कोई डैमेज न हो, यह सुनिश्चित करें। ब्ीमबा जीम वचमतंजपवद व िठच् ंदक थ्च् ंदहसम बवबो पद इवजी बंइे पद वचमद ंदक बसवेमक चवेपजपवदे ूपजी बंसपइतंजमक ठच् ंदक थ्च् हंनहमे बवददमबजमक ूपजी जीम कनउउलण् ।सेव बीमबा वित ंपत समंांहम पद ठच् ंदक थ्च् सिमगपइसम ीवेमे ंदक ंदहसम बवबोण् म्देनतम जीमतम पे दव कंउंहम पद जीम ठच्','Operation Normal',158,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','ii','Ensure all angle cocks have correct color coding.','सभी एंगल कॉक की सही कलर कोड सुनिश्चित करें।','Normal',159,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','iii','Check visually MU washer of BP & FP Hose pipes.','BP एवं FP होज़ पाइप्स की MU वॉशर की दृश्य जांच करें।','Normal',160,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','iv','In case of CRO, replace BP & FP hose pipes.','CRO की स्थिति में BP एवं FP होज़ पाइप्स को बदलें।','चेक किया ब्ीमबामक',161,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','v','Ensure protection guard is available on BP & FP angle cocks in both cabs. Also ensure that BP & FP hose pipes are not touching with available protection guard.','सुनिश्चित करें कि दोनों कैब में BP एवं FP एंगल कॉक्स पर प्रोटेक्शन गार्ड उपलब्ध है। साथ ही यह भी सुनिश्चित करें कि BP एवं FP होज़ पाइप्स उपलब्ध प्रोटेक्शन गार्ड से संपर्क में न हों।','Normal',162,1 WHERE @trip_template_new=1;
INSERT INTO div_trip_inspection_template_items(template_id,section_name,item_no,label_en,label_hi,standard_value,sort_order,is_required) SELECT @trip_template_id,'Fp Angle Cock And Hose Pipe','vi','Ensure Additional BP & FP cock handle position is in open condition.','सुनिश्चित करें कि अतिरिक्त BP एवं FP कॉक हैंडल की स्थिति ओपन (खुली) अवस्था में हो।','Normal',163,1 WHERE @trip_template_new=1;
