-- Step 2 additive seed for the approved TI source forms.
-- Preserves existing template IDs and historical inspection responses.
-- Review source catalogs and run only after schema/source approval.
START TRANSACTION;

SET @trip_template_new := ROW_COUNT();
SET @trip_template_id := (SELECT id FROM div_trip_inspection_templates WHERE inspection_type='TI_CONVENTIONAL' AND version_no='VVH-2025-08-SOURCE');
-- Items are inserted only when this version is first created; reruns do not alter existing rows.

SET @trip_template_new := ROW_COUNT();
SET @trip_template_id := (SELECT id FROM div_trip_inspection_templates WHERE inspection_type='TI_3PHASE' AND version_no='VVH-2025-08-SOURCE');
-- Items are inserted only when this version is first created; reruns do not alter existing rows.

COMMIT;
